BEGIN;

CREATE TABLE IF NOT EXISTS "SystemAccount" (
    "AccountID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "FullName" character varying(150) NOT NULL,
    "Email" character varying(256) NOT NULL,
    "PasswordHash" character varying(512) NOT NULL,
    "Role" smallint NOT NULL DEFAULT 0,
    "CreatedDate" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "CK_SystemAccount_Role" CHECK ("Role" IN (0, 1))
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_SystemAccount_EmailLower"
    ON "SystemAccount" (LOWER("Email"));

CREATE TABLE IF NOT EXISTS "RefreshToken" (
    "RefreshTokenID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "AccountID" integer NOT NULL,
    "TokenHash" character varying(64) NOT NULL,
    "CreatedDate" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "ExpiresDate" timestamp without time zone NOT NULL,
    "RevokedDate" timestamp without time zone NULL,
    "ReplacedByTokenHash" character varying(64) NULL,
    CONSTRAINT "FK_RefreshToken_SystemAccount" FOREIGN KEY ("AccountID")
        REFERENCES "SystemAccount" ("AccountID") ON DELETE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_RefreshToken_TokenHash"
    ON "RefreshToken" ("TokenHash");
CREATE INDEX IF NOT EXISTS "IX_RefreshToken_AccountID"
    ON "RefreshToken" ("AccountID");

ALTER TABLE "Task" ADD COLUMN IF NOT EXISTS "CreatedByID" integer NULL;
ALTER TABLE "Task" ADD COLUMN IF NOT EXISTS "UpdatedByID" integer NULL;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_Task_CreatedBy') THEN
        ALTER TABLE "Task"
            ADD CONSTRAINT "FK_Task_CreatedBy" FOREIGN KEY ("CreatedByID")
            REFERENCES "SystemAccount" ("AccountID") ON DELETE RESTRICT;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_Task_UpdatedBy') THEN
        ALTER TABLE "Task"
            ADD CONSTRAINT "FK_Task_UpdatedBy" FOREIGN KEY ("UpdatedByID")
            REFERENCES "SystemAccount" ("AccountID") ON DELETE SET NULL;
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS "IX_Task_CreatedByID" ON "Task" ("CreatedByID");
CREATE INDEX IF NOT EXISTS "IX_Task_UpdatedByID" ON "Task" ("UpdatedByID");

UPDATE "SystemAccount"
SET "FullName" = 'QE190133 Administrator',
    "PasswordHash" = 'PBKDF2-SHA256$210000$3pQ4HqfpyWoRUEi2TyMP4Q==$5c3c9Cx/KfRQK9RCugdnEMPdf0X0uOJ+PFpB7v6hcoY=',
    "Role" = 1
WHERE LOWER("Email") = 'admin.qe190133@tasktrack.com';

INSERT INTO "SystemAccount" ("FullName", "Email", "PasswordHash", "Role")
SELECT 'QE190133 Administrator', 'admin.qe190133@tasktrack.com',
       'PBKDF2-SHA256$210000$3pQ4HqfpyWoRUEi2TyMP4Q==$5c3c9Cx/KfRQK9RCugdnEMPdf0X0uOJ+PFpB7v6hcoY=', 1
WHERE NOT EXISTS (
    SELECT 1 FROM "SystemAccount" WHERE LOWER("Email") = 'admin.qe190133@tasktrack.com'
);

COMMIT;
